def segment(frames, silence=None):
    threshold = int(1000 / 30) if silence is None else silence
    start = None
    quiet = 0
    for i, active in enumerate(frames):
        if active:
            if start is None:
                start = i
            quiet = 0
            continue
        if start is None:
            continue
        quiet += 1
        if quiet >= threshold:
            return start, i - threshold + 1
    return 'none'

